import numpy as np
def D4(I):
    R=[np.eye(5,dtype=int)]
    for k in range(1,4): R.append(np.rot90(R[-1]))
    F=lambda x:np.fliplr(x)
    out=[]
    for x in R:
        for f in [lambda y:y, F]:
            out.append(f(x))
    return out
